bareSQL:
SELECT c.clip_id FROM clips c WHERE c.is_orphan = 0 AND c.current_path IN (
    SELECT current_path FROM clip_tags WHERE tag IN (?, ?, ?)
) ORDER BY LOWER(c.current_path) ASC, c.clip_id ASC

pathsSQL:
SELECT c.current_path FROM clips c WHERE c.is_orphan = 0 AND (c.current_path < '/Volumes/' OR c.current_path >= '/Volumes0' OR (c.current_path >= ? AND c.current_path < ?)) AND c.current_path IN (
    SELECT current_path FROM clip_tags WHERE tag IN (?, ?, ?)
) ORDER BY LOWER(c.current_path) ASC, c.clip_id ASC

